MAX_BALANCE = 10 ** 10
UINT64 = 1 << 64


def display_to_fraction(data, scale):
    """Read a DISPLAY numeric field the way GnuCOBOL's decimal runtime does.

    GnuCOBOL skips leading bytes whose low nibble is zero and then forms a
    base-10 integer from the remaining bytes using (byte - '0').  The result
    is put into an unsigned 64-bit value.  For normal numeric data this is
    simply the usual decimal value; this also reproduces GnuCOBOL's handling
    of malformed/short records.
    """
    index = 0
    while index < len(data) and (data[index] & 0x0F) == 0:
        index += 1

    if index == len(data):
        value = 0
    else:
        value = 0
        for byte in data[index:]:
            value = value * 10 + (byte - 0x30)
        value %= UINT64

    return Fraction(value, 10 ** scale)


def move_display_numeric(data):
    """MOVE a DISPLAY numeric field to another DISPLAY numeric field.

    For the layouts in this program GnuCOBOL copies the integer bytes and
    appends zeroes for the new decimal places.  NUL and space bytes are
    converted to zero digits by that MOVE.
    """
    return bytes(0x30 if byte in (0x00, 0x20) else byte for byte in data)


def format_number(value, width=10):
    """Store a number into an unsigned PIC 9(width) DISPLAY field."""
    if value < 0:
        value = -value
    integer_part = value.numerator // value.denominator
    integer_part %= 10 ** width
    return f"{integer_part:0{width}d}".encode("ascii")

